import json,re,unicodedata
from pathlib import Path
ROOT=Path('/workspace/sites/somm100-france-grapes'); OUT=ROOT/'research/italy-linked/islands.json'
B={k:[] for k in ['grapes','translations','existingUpdates','regions','wines','evidence','unresolved','corrections']}
D='2026-10-26'
def bi(x):
 a=x.split(' || '); return {'en':a[0], 'zh':a[1] if len(a)>1 else a[0]}
def save(): OUT.write_text(json.dumps(B,ensure_ascii=False,indent=2)+'\n')
ARS='https://www.arsacweb.it/i-vitigni-calabresi/'
ATLAS='https://www.frontiersin.org/journals/plant-science/articles/10.3389/fpls.2020.605934/full'
FAN='https://www.mdpi.com/2073-4395/11/8/1538'
