TITLES={'overview':'Overview || 概览','history':'History || 历史','geography':'Geography || 地理','climate':'Climate || 气候','soils':'Soils || 土壤','grapes':'Grapes || 品种','viticulture':'Viticulture || 栽培','law':'Appellation rules || 产区法规','vinification':'Vinification and ageing || 酿造与熟化','producers':'Producers and research || 生产者与研究','service':'Tasting and service || 品鉴与侍酒','identity':'Identity || 身份','styles':'Styles || 酒型','release':'Release and analysis || 上市与分析标准'}
def sec(key,refs,rows):
 return {'id':key,'title':bi(TITLES.get(key,key)), 'rows':[{'label':bi(a),'body':bi(b)} for a,b in rows], 'refs':refs}
def reg(id,name,parent,intro,grapes,sections,kind='appellation'):
 used=list(dict.fromkeys([x for s in sections for x in s['refs']]+[x for _,_,refs in grapes for x in refs]))
 r={'id':id,'name':name,'country':'Italy','kind':kind,'aliases':[],'intro':bi(intro),'facts':[{'label':bi('Classification || 分类'),'body':bi('Administrative region || 行政大区' if kind=='region' else name)}],'sections':sections,'grapes':[{'grapeId':g,'role':bi(role),'sourceIds':refs} for g,role,refs in grapes],'wines':[],'sources':[{'id':k,'title':SOURCES[k][0],'url':SOURCES[k][1]} for k in used],'reviewed':D,'questions':[],'coverage':bi('Selected documented grapes and denominations; this dossier is not a claim of exhaustive regional coverage. || 收录经核实的代表性品种与产区，不宣称已覆盖大区全部内容。')}
 if parent:r['parentId']=parent
 B['regions'].append(r);return r
