print('regional checkpoint',len(B['grapes']),len(B['regions']))
def questions(region,rows):
 r=next(r for r in B['regions'] if r['id']==region)
 for i,(group,q,a,refs) in enumerate(rows):
  r['questions'].append({'id':region+'-q'+str(i+1).zfill(2),'level':'foundation' if i<10 else 'advanced','group':group,'q':bi(q),'a':bi(a),'refs':refs})
  for k in refs:
   if not any(s['id']==k for s in r['sources']):r['sources'].append({'id':k,'title':SOURCES[k][0],'url':SOURCES[k][1]})
 assert len(rows)==30,(region,len(rows))
