# Regional edges for every new grape, retaining the actual source rather than inferred PDO eligibility.
for g in B['grapes']:
 for rn in ['Puglia','Calabria','Sicilia','Sardegna']:
  if not any(p['name']==rn for p in g['regions']):continue
  r=next(r for r in B['regions'] if r['id']=='it-'+rn.lower())
  if any(e['grapeId']==g['id'] for e in r['grapes']):continue
  sid='grape-'+g['id'];src=g['sources'][0]
  r['sources'].append({'id':sid,'title':src['title'],'url':src['url']})
  r['grapes'].append({'grapeId':g['id'],'role':bi('Documented regional cultivation or conservation; see the grape dossier for exact locality and identity. || 有文献的区域种植或保育；具体地点及身份见品种档案。'),'sourceIds':[sid]})
# Reverse associations for pre-existing canonical records, including exact PDO names.
existing_ids={g['id'] for g in json.loads((ROOT/'data/grape-varieties.json').read_text())}
new_ids={g['id'] for g in B['grapes']}
for r in B['regions']:
 for e in r['grapes']:
  if e['grapeId'] not in existing_ids:continue
  upd(e['grapeId'],[r['name']],[],[s['url'] for s in r['sources'] if s['id'] in e['sourceIds']])
# Aggregate updates so each pre-existing canonical ID is represented once.
merged={}
for u in B['existingUpdates']:
 z=merged.setdefault(u['id'],{'id':u['id'],'countriesAdd':[],'aliasesAdd':[],'regionsAdd':[],'sourcesAdd':[]})
 for k in ['countriesAdd','aliasesAdd','regionsAdd','sourcesAdd']:
  for v in u[k]:
   key=v if isinstance(v,str) else v.get('name',v.get('url'))
   if not any((w if isinstance(w,str) else w.get('name',w.get('url')))==key for w in z[k]):z[k].append(v)
B['existingUpdates']=list(merged.values())
# Exact reverse PDO links for new canonical records, with translations aligned.
for r in B['regions']:
 for e in r['grapes']:
  if e['grapeId'] not in new_ids:continue
  g=next(x for x in B['grapes'] if x['id']==e['grapeId']);t=next(x for x in B['translations'] if x['id']==e['grapeId'])
  if not any(x['name']==r['name'] for x in g['regions']):
   g['regions'].append({'name':r['name'],'country':'Italy','note':e['role']['zh']});t['regions'].append({'name':r['name'],'note':e['role']['en']})
# Integrity validation before hand-off.
allids=existing_ids|new_ids
assert len(new_ids)==len(B['grapes'])
assert not (existing_ids&new_ids),existing_ids&new_ids
assert {t['id'] for t in B['translations']}==new_ids
rids={r['id'] for r in B['regions']}
for r in B['regions']:
 sids={s['id'] for s in r['sources']}
 assert len(sids)==len(r['sources']),('duplicate source',r['id'])
 assert not r.get('parentId') or r['parentId'] in rids
 assert len(r['sections'])>=5
 assert sum(len(s['rows']) for s in r['sections'])>=15
 for s in r['sections']:assert set(s['refs'])<=sids,(r['id'],s['id'])
 for e in r['grapes']:
  assert e['grapeId'] in allids,(r['id'],e['grapeId'])
  assert set(e['sourceIds'])<=sids,(r['id'],e['sourceIds'])
 for q in r['questions']:assert set(q['refs'])<=sids,(r['id'],q['id'])
 if r['kind']=='region':
  assert len(r['questions'])==30
  assert sum(q['level']=='foundation' for q in r['questions'])==10
  assert len(r['sections'])>=8 and sum(len(s['rows']) for s in r['sections'])>=20
B['evidence']=[{'scope':'Puglia, Calabria, Sicilia, Sardegna','reviewed':D,'method':'Primary genetic studies, official regional conservation records, production specifications and producer technical sheets. Exact legal designations are separate records; uncertain accession identities remain unresolved.','counts':{'newGrapes':len(B['grapes']),'existingUpdates':len(B['existingUpdates']),'regions':len(B['regions']),'questions':sum(len(r['questions']) for r in B['regions'])}}]
save()
print('FINAL',len(B['grapes']),len(B['existingUpdates']),len(B['regions']),sum(len(r['questions']) for r in B['regions']))
